mapper.select:

where a.slot_type = #{slotType}
  and a.end_time > #{now}
  and (a.status = 'paid' or (a.status = 'approved' and a.lock_expire_at > #{now}))
order by a.slot_no, a.start_time

select count(*) from sys_promotion_application
where slot_type = #{slotType} and slot_no = #{slotNo}
  and start_time < #{endTime} and end_time > #{startTime}
  and (status = 'paid' or (status = 'approved' and lock_expire_at > #{now}))
and apply_id != #{excludeId}

select count(*) from sys_promotion_application

	status = 'pending'
	and slot_type = #{slotType}
